import { ModelMenu } from "./02-pill-composer/model-menu";
import { ActionsMenu } from "./02-pill-composer/actions-menu";
export default function AgentChatInputPillComposer() {
    const [draft, setDraft] = useState("");
    const [files, setFiles] = useState<File[]>([]);
    const [busy, setBusy] = useState(false);
    const [notice, setNotice] = useState("");
