    const fileRef = useRef<HTMLInputElement>(null);
    const rightRef = useRef<HTMLDivElement>(null);
    const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
    const [mirrorWidth, setMirrorWidth] = useState(377);
    const [rightWidth, setRightWidth] = useState(203);
    const [contentHeight, setContentHeight] = useState(40);
    const expanded = draft.includes("\n");
    const inputHeight = expanded ? Math.min(160, contentHeight) : 40;
    const reduce = useReducedMotion();
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    const geometry = reduce ? { duration: 0 } : { duration: 0.28, ease: ARTEMIS_EASE_OUT };
    useEffect(() => () => clearTimeout(timer.current), []);
    useLayoutEffect(() => { const input = inputRef.current, right = rightRef.current; if (!input || !right)
        return; const measure = () => { setMirrorWidth(Math.round(input.getBoundingClientRect().width)); setRightWidth(right.offsetWidth); }; measure(); const observer = new ResizeObserver(measure); observer.observe(input); observer.observe(right); return () => observer.disconnect(); }, []);
    useLayoutEffect(() => { if (mirrorRef.current)
        setContentHeight(mirrorRef.current.scrollHeight); }, [draft, mirrorWidth]);
    const send = () => { if ((!draft.trim() && !files.length) || busy)
        return; if (document.activeElement instanceof HTMLElement)
        document.activeElement.blur(); setNotice(files.length ? `Demo: message with ${files.length} attachment${files.length === 1 ? "" : "s"} received.` : `Demo: \u201C${draft.trim()}\u201D received.`); setDraft(""); setFiles([]); setBusy(true); clearTimeout(timer.current); timer.current = setTimeout(() => setBusy(false), 2400); };
    const stop = () => { clearTimeout(timer.current); setBusy(false); setNotice("Demo response stopped."); };
    const mode = busy ? "stop" : draft.trim() || files.length ? "send" : "voice";
    const label = mode === "stop" ? "Stop response" : mode === "send" ? "Send message" : "Start voice chat";
    return (<>
      <div className="art:relative art:w-full art:max-w-2xl">
