          <motion.form onSubmit={e => { e.preventDefault(); send(); }} className={"art:relative art:min-w-0 art:border art:border-border art:bg-background " + (expanded ? "art:rounded-3xl" : "art:rounded-full")} initial={false} animate={{ height: expanded ? inputHeight + 58 : 54 }} transition={geometry}>
            <motion.textarea ref={inputRef} value={draft} onChange={e => setDraft(e.target.value)} disabled={busy} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
        e.preventDefault();
        send();
    } }} rows={1} aria-label="Message" placeholder="Ask anything" className="art:min-w-0 art:resize-none art:rounded-2xl art:bg-transparent art:px-1 art:py-2.5 art:text-sm art:leading-5 art:text-foreground art:outline-none art:placeholder:text-muted-foreground art:disabled:opacity-50 art:absolute art:top-1.5 art:z-10" style={{ height: inputHeight, overflowY: contentHeight > 160 ? "auto" : "hidden" }} initial={false} animate={{ left: expanded ? 12 : 46, right: expanded ? 12 : rightWidth + 12 }} transition={geometry}/>
            <div className="art:flex art:h-10 art:items-center art:gap-1 art:pointer-events-none art:absolute art:inset-x-1.5 art:bottom-1.5">
              <div className="art:pointer-events-auto art:flex art:shrink-0 art:items-center">
