              </div>
              <div aria-hidden="true" className="art:flex-1"/>
              <div ref={rightRef} className="art:pointer-events-auto art:flex art:shrink-0 art:items-center art:gap-1">
                <ModelMenu className="art:inline-flex art:items-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border-border art:text-foreground art:text-sm art:focus-visible:outline-none art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring/40 art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:justify-between art:h-10 art:min-w-0 art:max-w-28 art:gap-1 art:border-0 art:bg-transparent art:px-2 art:hover:bg-foreground/5 art:@min-[640px]/artemis:max-w-40 art:rounded-full" value={model} onChange={setModel} disabled={busy}/>
                <motion.button {...press} disabled={busy} onClick={() => setNotice("Dictation hook \u2014 connect your speech-to-text service. This preview does not record audio.")} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:size-9 art:shrink-0 art:text-foreground art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:after:absolute art:after:-inset-0.5 art:rounded-full" aria-label="Dictate message" title="Dictate message" tabIndex={0}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mic art:size-5" aria-hidden="true">
                    <path d="M12 19v3"/>
                    <path d="M19 10v2a7 7 0 0 1-14 0v-2"/>
                    <rect x="9" y="2" width="6" height="13" rx="3"/>
                  </svg>
                </motion.button>
                <motion.button {...press} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:relative art:size-9 art:shrink-0 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:after:absolute art:after:-inset-0.5 art:bg-foreground art:text-background art:hover:bg-foreground/90 art:h-9 art:rounded-full" aria-label={label} title={label} tabIndex={0} onClick={() => mode === "send" ? send() : mode === "stop" ? stop() : setNotice("Voice chat hook \u2014 connect your voice service. This preview does not record audio.")}>
 <span className="art:relative art:inline-grid art:shrink-0 art:place-items-center art:overflow-hidden art:size-5"><AnimatePresence key={reduce ? mode : "icons"} initial={false} mode="popLayout"><motion.span key={mode} aria-hidden="true" className="art:col-start-1 art:row-start-1 art:inline-flex art:items-center art:justify-center art:will-change-[opacity,filter,transform]" initial={{ opacity: 0, filter: "blur(3px)", y: 12 }} animate={{ opacity: 1, filter: "blur(0px)", y: 0 }} exit={{ opacity: 0, filter: "blur(3px)", y: -12, transition: { duration: 0.14, ease: ARTEMIS_EASE_OUT } }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_SWAP}>{mode === "stop" ? <Square className="art:size-4 art:fill-current"/> : mode === "send" ? <ArrowUp className="art:size-5"/> : <AudioLines className="art:size-5"/>}</motion.span></AnimatePresence></span></motion.button>
              </div>
            </div>
          </motion.form>
          <textarea ref={mirrorRef} value={draft} aria-hidden="true" tabIndex={-1} readOnly rows={1} className="art:pointer-events-none art:invisible art:absolute art:h-0 art:min-h-0 art:resize-none art:overflow-hidden art:border-0 art:px-1 art:py-2.5 art:text-sm art:leading-5" style={{ width: mirrorWidth }}/>
          <input ref={fileRef} type="file" hidden multiple disabled={busy} onChange={event => { const selected = Array.from(event.currentTarget.files ?? []); setFiles(current => [...current, ...selected]); event.currentTarget.value = ""; }}/>
        </div>
        <output className="art:absolute art:inset-x-6 art:top-full art:-mt-9 art:text-center art:text-xs art:text-muted-foreground">{notice}</output>
